import random, json, subprocess, sys
target='''......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......'''
n=len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
seen=set(); stems=[]
for i in range(n):
    if i in pairs and i not in seen and i<pairs[i]:
        j=pairs[i]; run=[(i,j)]; seen.add(i); seen.add(j)
        k=i+1
        while k in pairs and pairs[k]==j-1 and k not in seen:
            run.append((k,pairs[k])); seen.add(k); seen.add(pairs[k]); k+=1; j-=1
        stems.append(run)
pairpos=set(pairs.keys())
# loops: all positions not in pairpos
loops=[i for i in range(n) if i not in pairpos]

random.seed(12345)
cands=[]
for trial in range(2000):
    seq=['A']*n
    for si,st in enumerate(stems):
        for k,(ik,jk) in enumerate(st):
            r=random.random()
            if r<0.5: seq[ik]='G'; seq[jk]='C'
            else: seq[ik]='C'; seq[jk]='G'
    # loops: mostly A, but random U/G sprinkled to break spurious
    for i in loops:
        r=random.random()
        if r<0.7: seq[i]='A'
        elif r<0.85: seq[i]='U'
        else: seq[i]=random.choice('GC')
    cands.append(''.join(seq))
with open('/tmp/cands.json','w') as f: json.dump(cands,f)
print(len(cands))
EOF
